import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('manager-plans-on-the-calendar', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: task-calendar', async () => {
    await app.open('task-calendar');
  });
  await test.step('action: add-task', async () => {
    await app.action('add-task');
  });
  await test.step('fill: {title: \'\', due: today 10:30}', async () => {
    await app.fill({ title: '', due: 'today 10:30' });
  });
  await test.step('submit', async () => {
    await app.submit();
  });
  await test.step('expect: {error: title}', async () => {
    await app.expectError('title');
  });
  await test.step('fill: {title: Plan on the calendar}', async () => {
    await app.fill({ title: 'Plan on the calendar' });
  });
  await test.step('submit', async () => {
    await app.submit({ saved: true });
  });
  await test.step('open_item: {where: {title: Plan on the calendar}}', async () => {
    await app.openItem({ where: { title: 'Plan on the calendar' }, created: true });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
});
